ON CONFLICT (class_id, user_id) DO NOTHING;
SELECT c.id, u.id, 'student'
FROM classes c CROSS JOIN users u
WHERE c.id IN ('a2000000-0000-0000-0000-000000000007', 'a2000000-0000-0000-0000-000000000008', 'a2000000-0000-0000-0000-000000000009', 'a2000000-0000-0000-0000-000000000010', 'a2000000-0000-0000-0000-000000000011', 'a2000000-0000-0000-0000-000000000012') AND u.id IN ('a1000000-0000-0000-0000-000000000201', 'a1000000-0000-0000-0000-000000000202', 'a1000000-0000-0000-0000-000000000203', 'a1000000-0000-0000-0000-000000000204', 'a1000000-0000-0000-0000-000000000205', 'a1000000-0000-0000-0000-000000000206', 'a1000000-0000-0000-0000-000000000207', 'a1000000-0000-0000-0000-000000000208', 'a1000000-0000-0000-0000-000000000209', 'a1000000-0000-0000-0000-000000000210', 'a1000000-0000-0000-0000-000000000211', 'a1000000-0000-0000-0000-000000000212', 'a1000000-0000-0000-0000-000000000213', 'a1000000-0000-0000-0000-000000000214', 'a1000000-0000-0000-0000-000000000215', 'a1000000-0000-0000-0000-000000000216')
ON CONFLICT (class_id, user_id) DO NOTHING;
SELECT c.id, u.id, 'student'
FROM classes c CROSS JOIN users u
WHERE c.id IN ('a2000000-0000-0000-0000-000000000013', 'a2000000-0000-0000-0000-000000000014', 'a2000000-0000-0000-0000-000000000015', 'a2000000-0000-0000-0000-000000000016', 'a2000000-0000-0000-0000-000000000017', 'a2000000-0000-0000-0000-000000000018') AND u.id IN ('a1000000-0000-0000-0000-000000000301', 'a1000000-0000-0000-0000-000000000302', 'a1000000-0000-0000-0000-000000000303', 'a1000000-0000-0000-0000-000000000304', 'a1000000-0000-0000-0000-000000000305', 'a1000000-0000-0000-0000-000000000306', 'a1000000-0000-0000-0000-000000000307', 'a1000000-0000-0000-0000-000000000308', 'a1000000-0000-0000-0000-000000000309', 'a1000000-0000-0000-0000-000000000310', 'a1000000-0000-0000-0000-000000000311', 'a1000000-0000-0000-0000-000000000312', 'a1000000-0000-0000-0000-000000000313', 'a1000000-0000-0000-0000-000000000314', 'a1000000-0000-0000-0000-000000000315', 'a1000000-0000-0000-0000-000000000316', 'a1000000-0000-0000-0000-000000000317', 'a1000000-0000-0000-0000-000000000318')
