ON CONFLICT (id) DO NOTHING;

-- ---------------------------------------------------------------------------
-- Entregas. El estado depende de la antigüedad del plazo, para que cada
-- pantalla tenga algo que enseñar:
--   * plazo de hace más de 8 días: casi todo corregido, algún pendiente y algún
--     alumno sin entregar;
--   * plazo reciente: la mayoría entregada y pendiente de corregir (la cola de
--     "Calificar" del profesorado);
--   * plazo futuro: algún borrador.
-- Hay entregas tardías (se descuenta la penalización si la tarea la tiene).
-- ---------------------------------------------------------------------------
SELECT b.aid, b.sid,
       CASE b.estado WHEN 'draft' THEN 'Borrador de «' || b.titulo || '», pendiente de terminar.'
                     ELSE 'Trabajo entregado: ' || b.titulo || '.' END,
       CASE WHEN b.r % 2 = 0 AND b.estado <> 'draft' THEN 'https://example.org/demo/entregas/' || left(b.sid::text, 8) || '.pdf' END,
       b.estado,
       CASE b.estado WHEN 'draft' THEN NULL
            ELSE CASE WHEN b.r % 7 = 0
                      THEN LEAST(now() - interval '1 hour', b.due_date + ((1 + b.r % 3) || ' days')::interval)
                      ELSE b.due_date - (((b.r % 20) + 1) || ' hours')::interval END END
FROM (
  SELECT a.id AS aid, e.user_id AS sid, a.title AS titulo, a.due_date,
         abs(hashtext(e.user_id::text || a.id::text)) % 100 AS r,
         CASE
           WHEN a.due_date >= now() THEN
             CASE WHEN abs(hashtext(e.user_id::text || a.id::text)) % 100 < 15 THEN 'draft' END
           WHEN now() - a.due_date > interval '8 days' THEN
             CASE WHEN abs(hashtext(e.user_id::text || a.id::text)) % 100 < 80 THEN 'graded'
                  WHEN abs(hashtext(e.user_id::text || a.id::text)) % 100 < 85 THEN 'submitted' END
           ELSE
             CASE WHEN abs(hashtext(e.user_id::text || a.id::text)) % 100 < 15 THEN 'graded'
                  WHEN abs(hashtext(e.user_id::text || a.id::text)) % 100 < 80 THEN 'submitted' END
         END AS estado
  FROM assignments a
  JOIN enrollments e ON e.class_id = a.class_id AND e.role_in_class = 'student'
  WHERE a.id::text LIKE 'a4%-0000-0000-0000-%' AND NOT a.group_assignment
) AS b
WHERE b.estado IS NOT NULL
ON CONFLICT (assignment_id, student_id) DO NOTHING;

-- Tareas grupales: todo el subgrupo comparte estado, contenido y momento de entrega
SELECT b.aid, b.sid,
       'Proyecto del ' || b.grupo || ': ' || b.titulo || '.',
       'https://example.org/demo/proyectos/' || left(b.gid::text, 8) || '.zip',
       b.estado,
       b.due_date - (((b.r % 20) + 1) || ' hours')::interval,
       b.gid
FROM (
  SELECT a.id AS aid, gm.user_id AS sid, a.title AS titulo, a.due_date, cg.id AS gid, cg.name AS grupo,
         abs(hashtext(cg.id::text || a.id::text)) % 100 AS r,
         CASE
           WHEN a.due_date >= now() THEN NULL
           WHEN now() - a.due_date > interval '8 days'
                THEN CASE WHEN abs(hashtext(cg.id::text || a.id::text)) % 100 < 85 THEN 'graded' END
           ELSE CASE WHEN abs(hashtext(cg.id::text || a.id::text)) % 100 < 25 THEN 'graded'
                     WHEN abs(hashtext(cg.id::text || a.id::text)) % 100 < 90 THEN 'submitted' END
         END AS estado
  FROM assignments a
  JOIN class_groups cg ON cg.class_id = a.class_id
  JOIN class_group_members gm ON gm.group_id = cg.id
  WHERE a.id::text LIKE 'a4%-0000-0000-0000-%' AND a.group_assignment
) AS b
WHERE b.estado IS NOT NULL
ON CONFLICT (assignment_id, student_id) DO NOTHING;

-- ---------------------------------------------------------------------------
-- Calificaciones de las tareas sin rúbrica. La nota se deriva de un hash para
-- que sea variada pero estable entre ejecuciones (entre el 50 y el 100 % de la
-- puntuación). Si la entrega llegó tarde y la tarea penaliza, se descuenta el
-- porcentaje y se conserva la nota original en raw_score.
-- ---------------------------------------------------------------------------
SELECT s.id,
       round(t.raw * CASE WHEN t.tarde THEN (100 - a.late_penalty_percent) / 100.0 ELSE 1 END, 2),
       t.raw,
       CASE (abs(hashtext(s.id::text)) % 4)
         WHEN 0 THEN 'Buen trabajo. Cuida la presentación.'
         WHEN 1 THEN 'Correcto, aunque falta justificar algún paso.'
         WHEN 2 THEN 'Muy completo. Sigue así.'
         ELSE        'Revisa los apartados marcados y vuelve a intentarlo la próxima vez.'
       END,
       profe.user_id,
       t.tarde,
       LEAST(now() - interval '1 hour', s.submitted_at + interval '2 days')
FROM submissions s
JOIN assignments a ON a.id = s.assignment_id
JOIN LATERAL (
  SELECT e.user_id FROM enrollments e
  WHERE e.class_id = a.class_id AND e.role_in_class = 'teacher'
  ORDER BY e.enrolled_at LIMIT 1
) AS profe ON true
JOIN LATERAL (
  SELECT round(a.points * (50 + abs(hashtext(COALESCE(s.class_group_id::text, s.student_id::text) || a.id::text)) % 51) / 100.0, 2) AS raw,
         (a.late_penalty_percent > 0 AND s.submitted_at > a.due_date) AS tarde
) AS t ON true
WHERE a.id::text LIKE 'a4%-0000-0000-0000-%' AND s.status = 'graded'
  AND NOT EXISTS (SELECT 1 FROM rubrics r WHERE r.assignment_id = a.id)
ON CONFLICT (submission_id) DO NOTHING;

-- Tareas con rúbrica: se crea la nota, se puntúa cada criterio y la nota final es la suma
SELECT s.id, 0, 0,
       'Corregido con la rúbrica: revisa el desglose por criterios.',
       profe.user_id, false,
       LEAST(now() - interval '1 hour', s.submitted_at + interval '2 days')
FROM submissions s
JOIN assignments a ON a.id = s.assignment_id
JOIN LATERAL (
  SELECT e.user_id FROM enrollments e
  WHERE e.class_id = a.class_id AND e.role_in_class = 'teacher'
  ORDER BY e.enrolled_at LIMIT 1
) AS profe ON true
WHERE a.id::text LIKE 'a4%-0000-0000-0000-%' AND s.status = 'graded'
  AND EXISTS (SELECT 1 FROM rubrics r WHERE r.assignment_id = a.id)
ON CONFLICT (submission_id) DO NOTHING;

SELECT g.id, c.id,
       round(c.max_points * (55 + abs(hashtext(COALESCE(s.class_group_id::text, s.student_id::text) || c.id::text)) % 46) / 100.0, 2)
FROM grades g
JOIN submissions s ON s.id = g.submission_id
JOIN assignments a ON a.id = s.assignment_id
JOIN rubrics r ON r.assignment_id = a.id
JOIN rubric_criteria c ON c.rubric_id = r.id
WHERE a.id::text LIKE 'a4%-0000-0000-0000-%'
ON CONFLICT (grade_id, criterion_id) DO NOTHING;

UPDATE grades g
SET score = t.suma, raw_score = t.suma
FROM (SELECT rs.grade_id, sum(rs.points) AS suma FROM rubric_scores rs GROUP BY rs.grade_id) AS t
WHERE g.id = t.grade_id
  AND g.submission_id IN (SELECT s.id FROM submissions s JOIN assignments a ON a.id = s.assignment_id
                          WHERE a.id::text LIKE 'a4%-0000-0000-0000-%')
  AND g.score <> t.suma;

-- ---------------------------------------------------------------------------
-- Exámenes tipo test: tres por clase (uno reciente, uno anterior ya corregido y un examen
-- final por venir que recopila preguntas de los anteriores). 4 preguntas y 10 puntos cada
-- uno; los vencidos llevan intentos y notas. La opción correcta cambia de sitio.
-- ---------------------------------------------------------------------------
ON CONFLICT (id) DO NOTHING;
ON CONFLICT (id) DO NOTHING;
ON CONFLICT (id) DO NOTHING;

-- Intentos de los exámenes ya vencidos: cerca del 88 % del alumnado lo hace
SELECT ex.id, e.user_id,
       ex.due_date - interval '2 days' + (abs(hashtext(e.user_id::text || ex.id::text)) % 1000) * interval '1 minute',
       ex.due_date - interval '2 days' + (abs(hashtext(e.user_id::text || ex.id::text)) % 1000) * interval '1 minute'
         + interval '18 minutes'
FROM exams ex
JOIN enrollments e ON e.class_id = ex.class_id AND e.role_in_class = 'student'
WHERE ex.id::text LIKE 'a5%-0000-0000-0000-%' AND ex.due_date < now()
  AND abs(hashtext(e.user_id::text || ex.id::text)) % 100 < 88
ON CONFLICT (exam_id, student_id) DO NOTHING;

-- Respuestas: cada alumno tiene un nivel (45-89 % de acierto) que decide si acierta cada pregunta
SELECT at.id, qs.id,
       CASE WHEN abs(hashtext(at.id::text || qs.id::text)) % 100 < 45 + abs(hashtext(at.student_id::text)) % 45
            THEN (SELECT o.id FROM exam_options o WHERE o.question_id = qs.id AND o.correct LIMIT 1)
            ELSE (SELECT w.id FROM (SELECT o.id, row_number() OVER (ORDER BY o.sort_order) AS rn
                                    FROM exam_options o WHERE o.question_id = qs.id AND NOT o.correct) w
                  WHERE w.rn = 1 + abs(hashtext(at.id::text || qs.id::text || 'x')) % 2)
       END
FROM exam_attempts at
JOIN exam_questions qs ON qs.exam_id = at.exam_id
WHERE at.exam_id::text LIKE 'a5%-0000-0000-0000-%'
ON CONFLICT (attempt_id, question_id) DO NOTHING;

-- Nota de cada intento: suma de los puntos de las preguntas acertadas
UPDATE exam_attempts at
SET score = COALESCE((SELECT sum(qs.points)
                      FROM exam_answers an
                      JOIN exam_questions qs ON qs.id = an.question_id
                      JOIN exam_options o ON o.id = an.selected_option_id
                      WHERE an.attempt_id = at.id AND o.correct), 0)
WHERE at.exam_id::text LIKE 'a5%-0000-0000-0000-%' AND at.submitted_at IS NOT NULL AND at.score IS NULL;

