-- ---------------------------------------------------------------------------
-- Notificaciones, con los mismos tipos y payload que emite la aplicación.
-- Las de hace más de seis días están casi todas leídas; las recientes, sin
-- leer, para que la campana de cada alumno tenga un contador distinto.
-- ---------------------------------------------------------------------------
SELECT e.user_id, 'assignment_created',
       jsonb_build_object('className', c.name, 'title', a.title, 'assignmentId', a.id::text),
       CASE WHEN a.created_at < now() - interval '6 days' AND abs(hashtext(e.user_id::text || a.id::text)) % 5 <> 0
            THEN a.created_at + interval '1 day' END,
       a.created_at
FROM assignments a
JOIN classes c ON c.id = a.class_id
JOIN enrollments e ON e.class_id = a.class_id AND e.role_in_class = 'student'
WHERE a.id::text LIKE 'a4%-0000-0000-0000-%'
  AND NOT EXISTS (SELECT 1 FROM notifications n WHERE n.user_id = e.user_id AND n.type = 'assignment_created'
                  AND n.payload->>'assignmentId' = a.id::text);

SELECT s.student_id, 'grade_published',
       jsonb_build_object('className', c.name, 'title', a.title, 'assignmentId', a.id::text),
       CASE WHEN g.graded_at < now() - interval '6 days' AND abs(hashtext(s.id::text)) % 5 <> 0
            THEN g.graded_at + interval '1 day' END,
       g.graded_at
FROM grades g
JOIN submissions s ON s.id = g.submission_id
JOIN assignments a ON a.id = s.assignment_id
JOIN classes c ON c.id = a.class_id
WHERE a.id::text LIKE 'a4%-0000-0000-0000-%'
  AND NOT EXISTS (SELECT 1 FROM notifications n WHERE n.user_id = s.student_id AND n.type = 'grade_published'
                  AND n.payload->>'assignmentId' = a.id::text);

SELECT e.user_id, 'announcement_created',
       jsonb_build_object('className', c.name, 'classId', c.id::text),
       CASE WHEN an.created_at < now() - interval '6 days' AND abs(hashtext(e.user_id::text || an.id::text)) % 5 <> 0
            THEN an.created_at + interval '1 day' END,
       an.created_at
FROM announcements an
JOIN classes c ON c.id = an.class_id
JOIN enrollments e ON e.class_id = an.class_id AND e.role_in_class = 'student'
WHERE an.id::text LIKE 'a8%-0000-0000-0000-%'
  AND NOT EXISTS (SELECT 1 FROM notifications n WHERE n.user_id = e.user_id AND n.type = 'announcement_created'
                  AND n.payload->>'classId' = c.id::text AND n.created_at = an.created_at);

SELECT e.user_id, 'exam_created',
       jsonb_build_object('className', c.name, 'title', ex.title, 'examId', ex.id::text),
       CASE WHEN ex.created_at < now() - interval '6 days' AND abs(hashtext(e.user_id::text || ex.id::text)) % 5 <> 0
            THEN ex.created_at + interval '1 day' END,
       ex.created_at
FROM exams ex
JOIN classes c ON c.id = ex.class_id
JOIN enrollments e ON e.class_id = ex.class_id AND e.role_in_class = 'student'
WHERE ex.id::text LIKE 'a5%-0000-0000-0000-%'
  AND NOT EXISTS (SELECT 1 FROM notifications n WHERE n.user_id = e.user_id AND n.type = 'exam_created'
                  AND n.payload->>'examId' = ex.id::text);
