  ('a8000000-0000-0000-0000-000000000011', 'a2000000-0000-0000-0000-000000000001', '10000000-0000-0000-0000-000000000011', 'Recordad que «Examen de análisis: derivadas e integrales» es tipo test, con corrección automática y un único intento. Repasad los materiales de «Análisis: derivadas e integrales».', true, (date_trunc('day', now()) + interval '-9 days 9 hours 0 minutes')),
  ('a8000000-0000-0000-0000-000000000012', 'a2000000-0000-0000-0000-000000000001', '10000000-0000-0000-0000-000000000011', 'Ya está disponible el material de «Álgebra lineal: matrices y sistemas» en la pestaña de Materiales. Cualquier duda, en el foro.', false, (date_trunc('day', now()) + interval '-3 days 9 hours 0 minutes')),
  ('a8000000-0000-0000-0000-000000000021', 'a2000000-0000-0000-0000-000000000002', 'a1000000-0000-0000-0000-000000000001', 'Recordad que «Examen de electromagnetismo» es tipo test, con corrección automática y un único intento. Repasad los materiales de «Interacción electromagnética».', true, (date_trunc('day', now()) + interval '-9 days 9 hours 0 minutes')),
