INSERT INTO forum_posts (id, thread_id, author_id, content, created_at) VALUES
  ('ad000000-0000-0000-0000-000000000011', 'ac000000-0000-0000-0000-000000000001', 'a1000000-0000-0000-0000-000000000104', '¿Cómo elijo u y dv en ∫x·eˣ dx? Siempre me lío con cuál derivar.', (date_trunc('day', now()) + interval '-6 days 17 hours 0 minutes')),
  ('ad000000-0000-0000-0000-000000000012', 'ac000000-0000-0000-0000-000000000001', '10000000-0000-0000-0000-000000000011', 'Usa la regla ALPES: u es la función que aparece antes en Algebraicas–Logarítmicas–Polinómicas–Exponenciales–Seno/coseno. Aquí u = x y dv = eˣ dx.', (date_trunc('day', now()) + interval '-5 days 10 hours 0 minutes')),
  ('ad000000-0000-0000-0000-000000000013', 'ac000000-0000-0000-0000-000000000001', 'a1000000-0000-0000-0000-000000000109', 'Gracias, ahora me sale: x·eˣ − eˣ + C.', (date_trunc('day', now()) + interval '-5 days 19 hours 0 minutes')),
  ('ad000000-0000-0000-0000-000000000021', 'ac000000-0000-0000-0000-000000000002', 'a1000000-0000-0000-0000-000000000107', 'No entiendo cómo se calcula el radio de la órbita geoestacionaria.', (date_trunc('day', now()) + interval '-6 days 17 hours 0 minutes')),
  ('ad000000-0000-0000-0000-000000000022', 'ac000000-0000-0000-0000-000000000002', 'a1000000-0000-0000-0000-000000000001', 'Iguala la fuerza gravitatoria a la centrípeta y usa el periodo de un día sideral: T = 86164 s. Despeja r y sale ≈ 42 164 km desde el centro de la Tierra.', (date_trunc('day', now()) + interval '-5 days 10 hours 0 minutes')),
  ('ad000000-0000-0000-0000-000000000023', 'ac000000-0000-0000-0000-000000000002', 'a1000000-0000-0000-0000-000000000112', 'Ahora lo veo, era cuestión de no olvidar pasar el periodo a segundos.', (date_trunc('day', now()) + interval '-5 days 19 hours 0 minutes')),
  ('ad000000-0000-0000-0000-000000000031', 'ac000000-0000-0000-0000-000000000003', 'a1000000-0000-0000-0000-000000000110', '¿Cuándo tengo que usar Kp en lugar de Kc en un problema?', (date_trunc('day', now()) + interval '-6 days 17 hours 0 minutes')),
  ('ad000000-0000-0000-0000-000000000032', 'ac000000-0000-0000-0000-000000000003', 'a1000000-0000-0000-0000-000000000002', 'Kp se usa cuando trabajas con presiones parciales de gases; Kc con concentraciones. Se relacionan con Kp = Kc·(RT)^Δn.', (date_trunc('day', now()) + interval '-5 days 10 hours 0 minutes')),
  ('ad000000-0000-0000-0000-000000000033', 'ac000000-0000-0000-0000-000000000003', 'a1000000-0000-0000-0000-000000000101', 'Perfecto, me faltaba acordarme del Δn de moles gaseosos.', (date_trunc('day', now()) + interval '-5 days 19 hours 0 minutes')),
  ('ad000000-0000-0000-0000-000000000041', 'ac000000-0000-0000-0000-000000000004', 'a1000000-0000-0000-0000-000000000113', '¿Hace falta nombrar todos los recursos del texto o solo los más relevantes?', (date_trunc('day', now()) + interval '-6 days 17 hours 0 minutes')),
  ('ad000000-0000-0000-0000-000000000042', 'ac000000-0000-0000-0000-000000000004', '10000000-0000-0000-0000-000000000013', 'Solo los relevantes y siempre con su función: no basta con nombrarlos, hay que explicar qué aportan al sentido del texto.', (date_trunc('day', now()) + interval '-5 days 10 hours 0 minutes')),
  ('ad000000-0000-0000-0000-000000000043', 'ac000000-0000-0000-0000-000000000004', 'a1000000-0000-0000-0000-000000000104', 'Entendido, mejor pocos y bien explicados.', (date_trunc('day', now()) + interval '-5 days 19 hours 0 minutes')),
  ('ad000000-0000-0000-0000-000000000051', 'ac000000-0000-0000-0000-000000000005', 'a1000000-0000-0000-0000-000000000102', '¿El dossier de la Transición se entrega en papel o en la plataforma?', (date_trunc('day', now()) + interval '-6 days 17 hours 0 minutes')),
  ('ad000000-0000-0000-0000-000000000052', 'ac000000-0000-0000-0000-000000000005', '10000000-0000-0000-0000-000000000012', 'En la plataforma, en PDF. Recordad citar las fuentes al final con el formato que vimos en clase.', (date_trunc('day', now()) + interval '-5 days 10 hours 0 minutes')),
  ('ad000000-0000-0000-0000-000000000053', 'ac000000-0000-0000-0000-000000000005', 'a1000000-0000-0000-0000-000000000107', 'Vale, gracias.', (date_trunc('day', now()) + interval '-5 days 19 hours 0 minutes')),
  ('ad000000-0000-0000-0000-000000000061', 'ac000000-0000-0000-0000-000000000006', 'a1000000-0000-0000-0000-000000000105', 'Why do we say "I wish I were taller" and not "I wish I was taller"?', (date_trunc('day', now()) + interval '-6 days 17 hours 0 minutes')),
  ('ad000000-0000-0000-0000-000000000062', 'ac000000-0000-0000-0000-000000000006', 'a1000000-0000-0000-0000-000000000003', 'Both are used in speech, but "were" is the formal subjunctive form and the one expected in written exams.', (date_trunc('day', now()) + interval '-5 days 10 hours 0 minutes')),
  ('ad000000-0000-0000-0000-000000000063', 'ac000000-0000-0000-0000-000000000006', 'a1000000-0000-0000-0000-000000000110', 'Thanks, I will use "were" then.', (date_trunc('day', now()) + interval '-5 days 19 hours 0 minutes')),
  ('ad000000-0000-0000-0000-000000000071', 'ac000000-0000-0000-0000-000000000007', 'a1000000-0000-0000-0000-000000000206', 'Sigo sin ver la diferencia práctica entre interfaz y clase abstracta.', (date_trunc('day', now()) + interval '-6 days 17 hours 0 minutes')),
  ('ad000000-0000-0000-0000-000000000072', 'ac000000-0000-0000-0000-000000000007', 'a1000000-0000-0000-0000-000000000004', 'Usa interfaz para definir un contrato que varias clases sin relación pueden cumplir; clase abstracta cuando compartís código y estado entre subclases de una misma familia.', (date_trunc('day', now()) + interval '-5 days 10 hours 0 minutes')),
  ('ad000000-0000-0000-0000-000000000073', 'ac000000-0000-0000-0000-000000000007', 'a1000000-0000-0000-0000-000000000211', 'Con el ejemplo de la biblioteca me ha quedado claro, gracias.', (date_trunc('day', now()) + interval '-5 days 19 hours 0 minutes')),
  ('ad000000-0000-0000-0000-000000000081', 'ac000000-0000-0000-0000-000000000008', 'a1000000-0000-0000-0000-000000000209', '¿Cuándo debo usar LEFT JOIN en vez de INNER JOIN?', (date_trunc('day', now()) + interval '-6 days 17 hours 0 minutes')),
  ('ad000000-0000-0000-0000-000000000082', 'ac000000-0000-0000-0000-000000000008', 'a1000000-0000-0000-0000-000000000005', 'Cuando quieras conservar las filas de la tabla izquierda aunque no tengan pareja en la derecha: por ejemplo clientes sin pedidos.', (date_trunc('day', now()) + interval '-5 days 10 hours 0 minutes')),
  ('ad000000-0000-0000-0000-000000000083', 'ac000000-0000-0000-0000-000000000008', 'a1000000-0000-0000-0000-000000000214', 'Justo lo que me pasaba en la consulta 12, ya sale.', (date_trunc('day', now()) + interval '-5 days 19 hours 0 minutes')),
  ('ad000000-0000-0000-0000-000000000091', 'ac000000-0000-0000-0000-000000000009', 'a1000000-0000-0000-0000-000000000212', '¿Por qué usar XSD si la DTD ya valida el documento?', (date_trunc('day', now()) + interval '-6 days 17 hours 0 minutes')),
  ('ad000000-0000-0000-0000-000000000092', 'ac000000-0000-0000-0000-000000000009', 'a1000000-0000-0000-0000-000000000006', 'XSD permite tipos de datos, espacios de nombres y restricciones más finas, y además es XML. La DTD solo valida la estructura.', (date_trunc('day', now()) + interval '-5 days 10 hours 0 minutes')),
  ('ad000000-0000-0000-0000-000000000093', 'ac000000-0000-0000-0000-000000000009', 'a1000000-0000-0000-0000-000000000201', 'Tiene sentido, gracias.', (date_trunc('day', now()) + interval '-5 days 19 hours 0 minutes')),
  ('ad000000-0000-0000-0000-000000000101', 'ac000000-0000-0000-0000-000000000010', 'a1000000-0000-0000-0000-000000000215', 'Al arrancar Ubuntu en VirtualBox me dice que no encuentra el disco. ¿Qué hago?', (date_trunc('day', now()) + interval '-6 days 17 hours 0 minutes')),
  ('ad000000-0000-0000-0000-000000000102', 'ac000000-0000-0000-0000-000000000010', 'a1000000-0000-0000-0000-000000000007', 'Comprueba que el disco virtual está asignado al controlador SATA y que el orden de arranque pone primero el disco. Si sigue igual, revisa el archivo .vdi en la ruta de la VM.', (date_trunc('day', now()) + interval '-5 days 10 hours 0 minutes')),
  ('ad000000-0000-0000-0000-000000000103', 'ac000000-0000-0000-0000-000000000010', 'a1000000-0000-0000-0000-000000000204', 'Era el orden de arranque, ya funciona.', (date_trunc('day', now()) + interval '-5 days 19 hours 0 minutes')),
  ('ad000000-0000-0000-0000-000000000111', 'ac000000-0000-0000-0000-000000000011', 'a1000000-0000-0000-0000-000000000202', 'Me sale un conflicto en el archivo pom.xml y no sé resolverlo.', (date_trunc('day', now()) + interval '-6 days 17 hours 0 minutes')),
  ('ad000000-0000-0000-0000-000000000112', 'ac000000-0000-0000-0000-000000000011', 'a1000000-0000-0000-0000-000000000004', 'Abre el archivo y busca los marcadores <<<<<<<, =======, >>>>>>>. Quédate con lo correcto, elimina los marcadores, haz git add y luego git commit.', (date_trunc('day', now()) + interval '-5 days 10 hours 0 minutes')),
  ('ad000000-0000-0000-0000-000000000113', 'ac000000-0000-0000-0000-000000000011', 'a1000000-0000-0000-0000-000000000207', 'Resuelto, gracias.', (date_trunc('day', now()) + interval '-5 days 19 hours 0 minutes')),
  ('ad000000-0000-0000-0000-000000000121', 'ac000000-0000-0000-0000-000000000012', 'a1000000-0000-0000-0000-000000000205', '¿El currículum tiene que ser de una sola página?', (date_trunc('day', now()) + interval '-6 days 17 hours 0 minutes')),
  ('ad000000-0000-0000-0000-000000000122', 'ac000000-0000-0000-0000-000000000012', 'a1000000-0000-0000-0000-000000000008', 'Lo recomendable a vuestro nivel es una página, con lo más relevante arriba. Adaptadlo a la oferta.', (date_trunc('day', now()) + interval '-5 days 10 hours 0 minutes')),
  ('ad000000-0000-0000-0000-000000000123', 'ac000000-0000-0000-0000-000000000012', 'a1000000-0000-0000-0000-000000000210', 'Gracias, lo recorto.', (date_trunc('day', now()) + interval '-5 days 19 hours 0 minutes')),
  ('ad000000-0000-0000-0000-000000000131', 'ac000000-0000-0000-0000-000000000013', 'a1000000-0000-0000-0000-000000000304', 'En 5 − x = 2, ¿por qué x vale 3 y no −3?', (date_trunc('day', now()) + interval '-6 days 17 hours 0 minutes')),
  ('ad000000-0000-0000-0000-000000000132', 'ac000000-0000-0000-0000-000000000013', '10000000-0000-0000-0000-000000000011', 'Pasa el 5 restando: −x = 2 − 5 = −3. Multiplicando por −1 en ambos lados sale x = 3.', (date_trunc('day', now()) + interval '-5 days 10 hours 0 minutes')),
  ('ad000000-0000-0000-0000-000000000133', 'ac000000-0000-0000-0000-000000000013', 'a1000000-0000-0000-0000-000000000309', 'Vale, me olvidaba del último paso.', (date_trunc('day', now()) + interval '-5 days 19 hours 0 minutes')),
  ('ad000000-0000-0000-0000-000000000141', 'ac000000-0000-0000-0000-000000000014', 'a1000000-0000-0000-0000-000000000307', '¿Por qué «té» lleva tilde y «te» no?', (date_trunc('day', now()) + interval '-6 days 17 hours 0 minutes')),
  ('ad000000-0000-0000-0000-000000000142', 'ac000000-0000-0000-0000-000000000014', '10000000-0000-0000-0000-000000000013', 'Es la tilde diacrítica: «té» es la bebida y «te» es un pronombre. Sirve para distinguir palabras iguales con distinto significado.', (date_trunc('day', now()) + interval '-5 days 10 hours 0 minutes')),
  ('ad000000-0000-0000-0000-000000000143', 'ac000000-0000-0000-0000-000000000014', 'a1000000-0000-0000-0000-000000000312', 'Ahora sí, gracias.', (date_trunc('day', now()) + interval '-5 days 19 hours 0 minutes')),
  ('ad000000-0000-0000-0000-000000000151', 'ac000000-0000-0000-0000-000000000015', 'a1000000-0000-0000-0000-000000000310', '¿Qué eran exactamente los reinos de taifas?', (date_trunc('day', now()) + interval '-6 days 17 hours 0 minutes')),
  ('ad000000-0000-0000-0000-000000000152', 'ac000000-0000-0000-0000-000000000015', '10000000-0000-0000-0000-000000000012', 'Fueron los pequeños reinos musulmanes en que se fragmentó Al-Ándalus a partir de 1031, tras la caída del Califato de Córdoba.', (date_trunc('day', now()) + interval '-5 days 10 hours 0 minutes')),
  ('ad000000-0000-0000-0000-000000000153', 'ac000000-0000-0000-0000-000000000015', 'a1000000-0000-0000-0000-000000000315', 'Gracias, ahora lo sitúo en el mapa.', (date_trunc('day', now()) + interval '-5 days 19 hours 0 minutes')),
  ('ad000000-0000-0000-0000-000000000161', 'ac000000-0000-0000-0000-000000000016', 'a1000000-0000-0000-0000-000000000313', 'Si el hielo es sólido, ¿por qué flota en el agua?', (date_trunc('day', now()) + interval '-6 days 17 hours 0 minutes')),
  ('ad000000-0000-0000-0000-000000000162', 'ac000000-0000-0000-0000-000000000016', 'a1000000-0000-0000-0000-000000000001', 'Porque al congelarse el agua ocupa más volumen y su densidad baja por debajo de la del agua líquida.', (date_trunc('day', now()) + interval '-5 days 10 hours 0 minutes')),
  ('ad000000-0000-0000-0000-000000000163', 'ac000000-0000-0000-0000-000000000016', 'a1000000-0000-0000-0000-000000000318', 'Qué curioso, gracias.', (date_trunc('day', now()) + interval '-5 days 19 hours 0 minutes')),
  ('ad000000-0000-0000-0000-000000000171', 'ac000000-0000-0000-0000-000000000017', 'a1000000-0000-0000-0000-000000000316', 'When do I use "gone" and when "went"?', (date_trunc('day', now()) + interval '-6 days 17 hours 0 minutes')),
  ('ad000000-0000-0000-0000-000000000172', 'ac000000-0000-0000-0000-000000000017', 'a1000000-0000-0000-0000-000000000003', '"Went" is the past simple: "I went to Cádiz". "Gone" is the past participle and needs an auxiliary: "I have gone".', (date_trunc('day', now()) + interval '-5 days 10 hours 0 minutes')),
  ('ad000000-0000-0000-0000-000000000173', 'ac000000-0000-0000-0000-000000000017', 'a1000000-0000-0000-0000-000000000303', 'Now it is clear, thank you.', (date_trunc('day', now()) + interval '-5 days 19 hours 0 minutes')),
  ('ad000000-0000-0000-0000-000000000181', 'ac000000-0000-0000-0000-000000000018', 'a1000000-0000-0000-0000-000000000301', 'En mi circuito la resistencia se calienta mucho. ¿Es normal?', (date_trunc('day', now()) + interval '-6 days 17 hours 0 minutes')),
  ('ad000000-0000-0000-0000-000000000182', 'ac000000-0000-0000-0000-000000000018', 'a1000000-0000-0000-0000-000000000009', 'Sí: la energía eléctrica se disipa en forma de calor (efecto Joule). Si se calienta demasiado, usa una resistencia de mayor potencia.', (date_trunc('day', now()) + interval '-5 days 10 hours 0 minutes')),
  ('ad000000-0000-0000-0000-000000000183', 'ac000000-0000-0000-0000-000000000018', 'a1000000-0000-0000-0000-000000000306', 'Vale, era de 1/4 W. La cambio.', (date_trunc('day', now()) + interval '-5 days 19 hours 0 minutes')),
